  "cartes.data1.ex": {"fr": "ex. {c}", "en": "e.g. {c}"},
  "cartes.data1.ex_filtre_vide": {"fr": "ex. une condition sur une colonne de la table", "en": "e.g. a condition on a column of the table"},
  "cartes.data1.ex_tri_vide": {"fr": "ex. colonne desc", "en": "e.g. column desc"},
  "cartes.data1.exporter_deck": {"fr": "Exporter le deck", "en": "Export deck"},
  "cartes.data1.exporter_deck_n": {"fr": "Exporter le deck — {n} carte(s)", "en": "Export deck — {n} card(s)"},
  "cartes.data1.fab_auraient": {"fr": "Auraient été fabriqués : ", "en": "Would have been invented: "},
  "cartes.data1.fab_detail": {"fr": "{n} slot(s) qu'aucune colonne n'alimente × {nc} carte(s) = {a} · + {b} emplacement(s) laissés vides par une colonne pourtant posée = {tot} au total, compté carte par carte par le moteur (jamais un produit).", "en": "{n} slot(s) fed by no column × {nc} card(s) = {a} · + {b} placement(s) left empty by a column that is mapped = {tot} in total, counted card by card by the engine (never a product)."},
  "cartes.data1.fab_fabriques": {"fr": "Fabriqués : ", "en": "Invented: "},
  "cartes.data1.fab_neutralises": {"fr": " Le mode « laisser vide » les a tous neutralisés : le fichier livré n'en porte aucun.", "en": " “Leave blank” mode neutralized all of them: the delivered file contains none."},
  "cartes.data1.gab_t_base": {"fr": "{tot} = {n} slot(s) qu'aucune colonne n'alimente", "en": "{tot} = {n} slot(s) fed by no column"},
  "cartes.data1.gab_t_livre": {"fr": ". Le grand livre ci-dessous en compte {n} : il classe les colonnes, pas les prises de parole.", "en": ". The ledger below counts {n}: it sorts columns, not the places where the template speaks."},
  "cartes.data1.gab_t_seul": {"fr": " + {n} slot(s) pourtant mappé(s) dont la colonne a des cellules vides ({slots})", "en": " + {n} slot(s) that are mapped but whose column has empty cells ({slots})"},
  "cartes.data1.gab_t_texte": {"fr": " Mode « texte du gabarit » : ces slots impriment la valeur de démonstration de la pièce 03.", "en": " “Template text” mode: these slots print the sample value from piece 03."},
  "cartes.data1.gab_t_vide": {"fr": " Mode « laisser vide » actif : le gabarit ne reprend la main nulle part, soit {n} emplacement(s) évité(s) sur l'ensemble du tirage.", "en": " “Leave blank” mode is on: the template never takes over, so {n} placement(s) avoided across the whole print run."},
  "cartes.data1.geom": {"fr": "À <b>{dpi} DPI</b>, re-dérivé des millimètres : coupe {tw} × {th} mm → <b>{pw} × {ph} px</b> · + 2 × {bleed} mm de fond perdu → toile <b>{cw} × {ch} px</b> · − 2 × {safe} mm → zone sûre <b>{sw} × {sh} px</b>", "en": "At <b>{dpi} DPI</b>, re-derived from millimetres: trim {tw} × {th} mm → <b>{pw} × {ph} px</b> · + 2 × {bleed} mm bleed → canvas <b>{cw} × {ch} px</b> · − 2 × {safe} mm → safe zone <b>{sw} × {sh} px</b>"},
  "cartes.data1.geom_aucun": {"fr": ". Aucun fichier mesuré pour l'instant : le bouton ci-dessus en rend deux et les lit octet par octet.", "en": ". No file measured yet: the button above renders two and reads them byte by byte."},
  "cartes.data1.geom_core": {"fr": " — <b>la table du CORE annonce autre chose ({w} × {h})</b>", "en": " — <b>the CORE table says otherwise ({w} × {h})</b>"},
  "cartes.data1.ghost_t": {"fr": "{cols} — ces colonnes visent un slot qui n'existe plus dans « 03 Typographie » : elles n'alimentent rien, reposez-les", "en": "{cols} — these columns target a slot that no longer exists in “03 Typography”: they feed nothing, map them again"},
  "cartes.data1.gs_bouton": {"fr": "Lien Google Sheets…", "en": "Google Sheets link…"},
  "cartes.data1.gs_bouton_t": {"fr": "Importer une feuille Google Sheets partagée « tous les utilisateurs disposant du lien » (CSV public, gratuit, sans clé)", "en": "Import a Google Sheets sheet shared with “anyone with the link” (public CSV, free, no key)"},
