  "cartes.face.fitwin_t": {"fr": "pose en « couvrir » au centre de la fenêtre d'illustration", "en": "places the image in “cover” mode at the center of the art window"},
  "cartes.face.formule_debut": {"fr": "Toile {w} × {h} px à {dpi} DPI · DPI effectif = plus petit de", "en": "Canvas {w} × {h} px at {dpi} DPI · effective DPI = smaller of"},
  "cartes.face.formule_fin": {"fr": ", arrondi à {n} — le nombre de la jauge", "en": ", rounded to {n} — the gauge's number"},
