  "cartes.face.ihdr": {"fr": "<b>{w} x {h} px</b>, {d} bits par canal (IHDR, octet 9), type {t} = <b>{nom}</b>", "en": "<b>{w} x {h} px</b>, {d} bits per channel (IHDR, byte 9), type {t} = <b>{nom}</b>"},
  "cartes.face.il_faudrait": {"fr": "Il faudrait une source de <b>{w} × {h} px</b> à cette taille de pose.", "en": "You would need a <b>{w} × {h} px</b> source at this placement size."},
  "cartes.face.image_importee": {"fr": "image importée", "en": "imported image"},
  "cartes.face.import_n": {"fr": "import de {n} illustration(s)…", "en": "importing {n} illustration(s)…"},
  "cartes.face.import_reduit": {"fr": "fichier déposé {w} × {h} px, ramené à {max} px de côté à l'import : c'est la trame ci-dessus qui est posée et mesurée.", "en": "dropped file {w} × {h} px, scaled down to {max} px per side on import: the raster above is what is placed and measured."},
  "cartes.face.import_rien": {"fr": "l'import n'a rien retenu", "en": "the import kept nothing"},
  "cartes.face.invite": {"fr": "Invite", "en": "Prompt"},
