  "cartes.face.jauge_vide": {"fr": "Choisissez une face du catalogue, déposez une image ou générez-la. La jauge affichera alors le DPI réel de l'impression.", "en": "Pick a face from the catalog, drop an image or generate one. The gauge will then show the real print DPI."},
  "cartes.face.lecture": {"fr": " · fenêtre {w} x {h} px ({wmm} x {hmm} mm, {pct} % de la SURFACE de la toile) · origine {ox} / {oy} px · décalage {dx} / {dy} px · illustration : {src}", "en": " · window {w} x {h} px ({wmm} x {hmm} mm, {pct} % of the canvas AREA) · origin {ox} / {oy} px · offset {dx} / {dy} px · illustration: {src}"},
  "cartes.face.mesure_echec": {"fr": "la mesure a échoué : ", "en": "the measurement failed: "},
  "cartes.face.mesure_en_cours": {"fr": "mesure en cours…", "en": "measuring…"},
  "cartes.face.meta_relues": {"fr": "<br>métadonnées relues : ", "en": "<br>metadata read back: "},
  "cartes.face.mire_aide": {"fr": "Un damier dessiné à la demande, rangé dans la pile comme une image déposée : posez-le pour caler le cadrage et la fenêtre d'illustration, retirez-le d'un clic. Sa vignette porte sa taille et son DPI comme les autres.", "en": "A checkerboard drawn on demand, stored in the stack like a dropped image: place it to line up the framing and the art window, remove it with one click. Its thumbnail shows its size and DPI like the others."},
  "cartes.face.mire_btn": {"fr": "Mire de contrôle {w} × {h} px", "en": "Test pattern {w} × {h} px"},
  "cartes.face.modele": {"fr": "Modèle", "en": "Model"},
  "cartes.face.net_entrees": {"fr": " : {avant} entrées avant, {apres} après", "en": ": {avant} entries before, {apres} after"},
  "cartes.face.net_ligne": {"fr": "<b>Mesuré à l'instant</b> : {n} vignettes peintes en {ms} ms — <b>{img} image téléchargée</b>.", "en": "<b>Measured just now</b>: {n} thumbnails painted in {ms} ms — <b>{img} image downloaded</b>."},
  "cartes.face.net_na": {"fr": "Compteur réseau indisponible sur ce moteur.", "en": "Network counter unavailable in this engine."},
  "cartes.face.nodb": {"fr": "Le stockage local du navigateur est indisponible : la pile ne survivra pas au rechargement.", "en": "The browser's local storage is unavailable: the stack will not survive a reload."},
  "cartes.face.nombre": {"fr": "Nombre", "en": "Count"},
