  "cartes.face.onglet_vec_t": {"fr": "Documents vectoriels du jeu (Vectorlab)", "en": "The deck's vector documents (Vectorlab)"},
  "cartes.face.ouvrir": {"fr": "Ouvrir", "en": "Open"},
  "cartes.face.palette_lbl": {"fr": "Palette — le même dessin, {n} teintes", "en": "Palette — the same drawing, {n} hues"},
  "cartes.face.papier_en_cours": {"fr": "Ce qui atteint le papier : mesure en cours…", "en": "What reaches the paper: measuring…"},
  "cartes.face.papier_masque": {"fr": " — le cadre et les textes en masquent {d} points de plus.", "en": " — the frame and text boxes hide {d} more points."},
  "cartes.face.papier_non_mesurable": {"fr": "Ce qui atteint le papier : <b>non mesurable</b> — deux rendus identiques de cette carte diffèrent de {n} pixels, une couche du dessus n'est pas déterministe. Aucun pourcentage ne serait vérifiable ici.", "en": "What reaches the paper: <b>not measurable</b> — two identical renders of this card differ by {n} pixels, a layer above is not deterministic. No percentage could be verified here."},
  "cartes.face.papier_pct": {"fr": "Sur la carte imprimée : <b>{p} % de la pose atteint le papier</b>", "en": "On the printed card: <b>{p} % of the placed image reaches the paper</b>"},
  "cartes.face.passer_contenir": {"fr": "Passer en « Contenir »", "en": "Switch to “Contain”"},
  "cartes.face.ph_aucune": {"fr": "Aucune illustration", "en": "No illustration"},
