  "cartes.face.ph_piochez": {"fr": "piochez au catalogue ou générez-la", "en": "pick from the catalog or generate one"},
  "cartes.face.phys_aucun": {"fr": " · <b>aucun pHYs</b> — le fichier n'annonce aucune résolution physique", "en": " · <b>no pHYs</b> — the file declares no physical resolution"},
  "cartes.face.phys_ligne": {"fr": "{ppm} px/m (unité mètre) = <b>{dpif} DPI</b> — pHYs ne stocke que des entiers de pixels par mètre, et {dpi} DPI en vaut {exact}.", "en": "{ppm} px/m (unit: metre) = <b>{dpif} DPI</b> — pHYs only stores whole pixels per metre, and {dpi} DPI is {exact}."},
  "cartes.face.phys_relu": {"fr": " · <b>pHYs</b> {x} x {y} px/m (unité {u} = mètre) = <b>{dpi} DPI</b>", "en": " · <b>pHYs</b> {x} x {y} px/m (unit {u} = metre) = <b>{dpi} DPI</b>"},
  "cartes.face.pile_vide": {"fr": "La pile est vide. Déposez plusieurs fichiers d'un coup, collez une image (Ctrl+V) ou piochez dans le catalogue — {n} dessins vectoriels vous attendent.", "en": "The stack is empty. Drop several files at once, paste an image (Ctrl+V) or pick from the catalog — {n} vector drawings are waiting."},
  "cartes.face.plage": {"fr": "({rgb}) {p} % de la source → <b>{a}</b> px après la pose, <b>{b}</b> px dans la carte livrée", "en": "({rgb}) {p} % of the source → <b>{a}</b> px after placement, <b>{b}</b> px in the delivered card"},
  "cartes.face.plages": {"fr": "Plages plates de la source : {plages}.", "en": "Flat areas of the source: {plages}."},
  "cartes.face.png_aide": {"fr": "Le fichier emporte sa résolution physique (<b>pHYs</b>), son espace de couleur (<b>sRGB</b>) et le nom de la carte. Sans eux, une mise en page ouvre le PNG à 72 DPI. À {dpi} DPI : ", "en": "The file carries its physical resolution (<b>pHYs</b>), its color space (<b>sRGB</b>) and the card name. Without them, a layout tool opens the PNG at 72 DPI. At {dpi} DPI: "},
  "cartes.face.png_label": {"fr": "Télécharger la face — PNG 1:1 avec sa résolution physique", "en": "Download the face — 1:1 PNG with its physical resolution"},
  "cartes.face.png_livre": {"fr": "PNG livré : résolution, espace de couleur et métadonnées dans les octets", "en": "PNG delivered: resolution, color space and metadata in the bytes"},
  "cartes.face.pose_recadree": {"fr": "pose recadrée sur la fenêtre d'illustration", "en": "image refitted to the art window"},
  "cartes.face.posee": {"fr": "illustration posée", "en": "illustration placed"},
  "cartes.face.posee_a": {"fr": "posée à {cible} DPI exactement", "en": "placed at exactly {cible} DPI"},
  "cartes.face.preuve_a": {"fr": "<b>Recompté sur les octets rendus</b>, {ms} ms. (a) les {n} dessins peints dans la <b>même</b> palette ({pal}, {w}×{h} px) donnent <b>{d} / {n} empreintes distinctes</b>.", "en": "<b>Recounted on the rendered bytes</b>, {ms} ms. (a) the {n} drawings painted in the <b>same</b> palette ({pal}, {w}×{h} px) give <b>{d} / {n} distinct fingerprints</b>."},
  "cartes.face.preuve_b": {"fr": "(b) les {n} combinaisons ({w}×{h} px) donnent <b>{d} / {total} empreintes distinctes</b>.", "en": "(b) the {n} combinations ({w}×{h} px) give <b>{d} / {total} distinct fingerprints</b>."},
  "cartes.face.preuve_hash": {"fr": "FNV-1a 32 bits sur getImageData, canaux R/V/B", "en": "32-bit FNV-1a on getImageData, R/G/B channels"},
  "cartes.face.preuve_paire": {"fr": "Paire la plus <b>proche</b> : « {a} » et « {b} » — <b>{pct} % des {px} pixels</b> diffèrent, de <b>{moy} niveaux</b> en moyenne sur ceux-là (maximum {max}), soit {best} niveau(x)/canal ramené à la vignette entière — fond commun compris.", "en": "<b>Closest</b> pair: “{a}” and “{b}” — <b>{pct} % of the {px} pixels</b> differ, by <b>{moy} levels</b> on average over those (maximum {max}), i.e. {best} level(s)/channel over the whole thumbnail — shared background included."},
  "cartes.face.prompt_ph": {"fr": "décrivez la face de la carte…", "en": "describe the card face…"},
  "cartes.face.proportions": {"fr": "Proportions", "en": "Aspect ratio", "contexte": true},
  "cartes.face.quoi_carte": {"fr": "déposée(s) sur la carte", "en": "dropped on the card"},
  "cartes.face.quoi_collee": {"fr": "collée(s)", "en": "pasted"},
  "cartes.face.quoi_deja": {"fr": "déjà dans la pile — reposée plutôt que réimportée", "en": "already in the stack — placed again instead of re-imported"},
