  "cartes.forge3d.lien_refuse": {"fr": "« {de} » ne se branche pas sur « {vers} » — chaîne attendue : {chaine}", "en": "« {de} » does not connect to « {vers} » — expected chain: {chaine}"},
  "cartes.forge3d.maillon_partage_mat": {"fr": "cette matière appartient déjà à une autre chaîne — un maillon partagé se fait réécrire par la première rangée éditée, et l'autre chaîne perd son lien en silence.", "en": "this material already belongs to another chain — a shared link gets rewritten by the first edited row, and the other chain silently loses its link."},
  "cartes.forge3d.maillon_partage_trs": {"fr": "ce placement appartient déjà à une autre chaîne — un maillon partagé se fait réécrire par la première rangée éditée, et l'autre chaîne perd son lien en silence.", "en": "this placement already belongs to another chain — a shared link gets rewritten by the first edited row, and the other chain silently loses its link."},
  "cartes.forge3d.manifeste_non_charge": {"fr": "manifeste de cette carte non chargé — réessayez", "en": "manifest for this card not loaded — try again"},
  "cartes.forge3d.matiere": {"fr": "matière", "en": "material"},
  "cartes.forge3d.matiere_hors_chaine": {"fr": "matière hors chaîne — aucun traitement ne la porte.", "en": "material outside any chain — no process carries it."},
  "cartes.forge3d.matiere_inconnue": {"fr": "matière inconnue de ce contrat", "en": "material unknown to this contract"},
  "cartes.forge3d.matiere_muette": {"fr": "l'écran ne peut pas dire ce que cette matière porte (occlusion, relief, couleur). Les réglages du graphe, eux, agissent toujours à la construction.", "en": "the screen cannot tell what this material carries (occlusion, relief, color). The graph settings still apply at build time."},
  "cartes.forge3d.matiere_plan_relief": {"fr": "matière sur plan/relief seulement — un GLB moteur garde la sienne.", "en": "material on plane/relief only — an engine GLB keeps its own."},
  "cartes.forge3d.meshy_absente": {"fr": "clé Meshy absente — Réglages", "en": "Meshy key missing — Settings"},
  "cartes.forge3d.meshy_mock": {"fr": "simulateur Meshy local actif — aucun crédit réel n'est débité.", "en": "local Meshy simulator on — no real credit is charged."},
  "cartes.forge3d.montant_inconnu": {"fr": "un montant inconnu pour {n} nœud(s) (table des moteurs indisponible)", "en": "an unknown amount for {n} node(s) (engine table unavailable)"},
