  "cartes.forge3d.route_absente": {"fr": "route absente sur ce backend (reponse non JSON)", "en": "route missing on this backend (non-JSON response)"},
  "cartes.forge3d.sans_ao": {"fr": "cette matière ne porte AUCUNE carte d'occlusion (le disque fait foi) : la case ne changera rien au fichier.", "en": "this material carries NO occlusion map (the disk is the reference): the box will change nothing in the file."},
