  "cartes.forge3d.translucide_moyenne": {"fr": "avec la <b>moyenne de l'image</b> de la matière choisie (pas son réglage de couleur : les deux diffèrent sur toute la boutique).", "en": "with the <b>average of the image</b> of the chosen material (not its color setting: the two differ across the whole shop)."},
  "cartes.forge3d.translucide_pref": {"fr": "« translucide » teinte en plus son absorption", "en": "« translucide » also tints its absorption"},
  "cartes.forge3d.translucide_reglage": {"fr": "avec le réglage de couleur de la matière{ici} — elle n'a pas d'image.", "en": "with the material color setting{ici} — it has no image."},
  "cartes.forge3d.translucide_sans": {"fr": "avec la couleur de la matière — aucune matière posée : il ne teinte rien.", "en": "with the material color — no material set: it tints nothing."},
  "cartes.forge3d.trop_elements": {"fr": "<b>{n} éléments</b> — le maximum construisible est {max} : retire des rangs, la construction refuserait.", "en": "<b>{n} elements</b> — the buildable maximum is {max}: remove rows, the build would refuse."},
