  "cartes.frame1.raccourcis": {"fr": "<b>Raccourcis</b> — <kbd>Ctrl+Z</kbd>/<kbd>Ctrl+Maj+Z</kbd> annuler / rétablir · <kbd>[</kbd> <kbd>]</kbd> famille · <kbd>,</kbd> <kbd>.</kbd> rareté · <kbd>D</kbd> double filet · <kbd>M</kbd> métal · <kbd>G</kbd> gemme · <kbd>V</kbd> recto/verso", "en": "<b>Shortcuts</b> — <kbd>Ctrl+Z</kbd>/<kbd>Ctrl+Shift+Z</kbd> undo / redo · <kbd>[</kbd> <kbd>]</kbd> family · <kbd>,</kbd> <kbd>.</kbd> rarity · <kbd>D</kbd> double line · <kbd>M</kbd> metal · <kbd>G</kbd> gem · <kbd>V</kbd> front/back"},
