  "cartes.frame2.alpha_absent": {"fr": "RGB : aucun canal alpha dans le fichier", "en": "RGB: no alpha channel in the file"},
  "cartes.frame2.aucun_calque": {"fr": "Aucun calque. « Ajouter un calque » pose un motif, une texture ou une matière par-dessus l'image de fond.", "en": "No layers. “Add layer” places a pattern, texture or material over the background image."},
  "cartes.frame2.aucun_modele": {"fr": "aucun modèle disponible", "en": "no model available"},
  "cartes.frame2.aucune_image": {"fr": "le fournisseur n'a rendu aucune image", "en": "the provider returned no image"},
  "cartes.frame2.badge_ecarts": {"fr": "{n} écart(s) · {t}", "en": "{n} discrepancy(ies) · {t}"},
  "cartes.frame2.balayage_impossible": {"fr": "balayage impossible", "en": "sweep failed"},
  "cartes.frame2.borne_a": {"fr": "marge et retrait ≤ {cap} mm sur {fmt} (BAND_MIN_MM = {band} mm d'ouverture)", "en": "margin and inset ≤ {cap} mm on {fmt} (BAND_MIN_MM = {band} mm opening)"},
  "cartes.frame2.borne_m": {"fr": "marge demandée {m} mm → tracée {mt} mm · retrait {r} → {rt} mm", "en": "requested margin {m} mm → drawn {mt} mm · inset {r} → {rt} mm"},
  "cartes.frame2.borne_note": {"fr": "sans elle, micro à 20 mm donnait une bande de -8,25 mm", "en": "without it, micro at 20 mm gave a -8.25 mm band"},
  "cartes.frame2.borne_q": {"fr": "La borne du format est appliquée", "en": "The format limit is applied"},
  "cartes.frame2.choisir_fichier": {"fr": "choisir un fichier…", "en": "choose a file…"},
  "cartes.frame2.cout_sans_tarif": {"fr": "Coût de ce clic : <b>1 image</b> chez {qui}. <b>Tarif non tabulé</b> dans l'application : aucun montant n'est affiché ici, plutôt qu'un montant emprunté à un autre modèle.", "en": "Cost of this click: <b>1 image</b> from {qui}. <b>Price not listed</b> in the app: no amount is shown here, rather than one borrowed from another model."},
  "cartes.frame2.cout_tarif": {"fr": "Coût de ce clic : <b>1 × {prix} = {prix}</b> chez {qui}. Tarif lu dans {source}.", "en": "Cost of this click: <b>1 × {prix} = {prix}</b> from {qui}. Price read from {source}."},
  "cartes.frame2.decor_aucun": {"fr": "<b>Aucun décor</b> — le cadre est entièrement tracé. Une image générée ici devient le fond de la bande : elle couvre la toile <b>fond perdu compris</b>, jamais la fenêtre d'illustration.", "en": "<b>No decor</b> — the frame is fully drawn. An image generated here becomes the band background: it covers the canvas <b>including bleed</b>, never the art window."},
  "cartes.frame2.decor_etat": {"fr": "Décor <b>{nom}</b> à <b>{pct} %</b>, posé <b>sous la matière</b> (les trames, la patine et les usures repassent par-dessus) et <b>sous la moulure</b>. Il vit dans le magasin d'images de l'application — le même que l'illustration. Enregistré comme <b>modèle</b>, le cadre garde l'opacité mais <b>pas le fichier</b>.", "en": "Decor <b>{nom}</b> at <b>{pct}%</b>, placed <b>under the material</b> (screens, patina and wear go over it) and <b>under the moulding</b>. It lives in the app's image store — the same as the art. Saved as a <b>template</b>, the frame keeps the opacity but <b>not the file</b>."},
  "cartes.frame2.decor_genere": {"fr": "décor généré et posé sur le cadre", "en": "decor generated and applied to the frame"},
  "cartes.frame2.decor_sans_modele": {"fr": "<b>Aucun modèle d'image disponible</b> — aucune clé n'est enregistrée dans les Réglages de l'application, la génération échouerait. Le reste de ce panneau ne demande aucune clé.", "en": "<b>No image model available</b> — no key is saved in the app Settings, so generation would fail. The rest of this panel needs no key."},
  "cartes.frame2.depart_auto": {"fr": "départ automatique…", "en": "starting automatically…"},
  "cartes.frame2.descendre": {"fr": "descendre (peint plus tard)", "en": "move down (painted later)"},
  "cartes.frame2.dos_calques.plusieurs": {"fr": " <b>{n} / {max}</b> calques : l'ordre de la liste EST l'ordre de peinture, et « Multiplier » est <b>précomposé dans les pixels</b> du calque — la preuve d'empilement de l'export par couches reste verte. Enregistré comme <b>modèle</b>, ce verso garde ses réglages mais <b>pas ses fichiers</b> : ils restent dans ce jeu.", "en": " <b>{n} / {max}</b> layers: the list order IS the paint order, and “Multiply” is <b>baked into the layer's pixels</b> — the layered-export stacking proof stays green. Saved as a <b>template</b>, this back keeps its settings but <b>not its files</b>: they stay in this deck."},
  "cartes.frame2.dos_calques.un": {"fr": " <b>{n} / {max}</b> calque : l'ordre de la liste EST l'ordre de peinture, et « Multiplier » est <b>précomposé dans les pixels</b> du calque — la preuve d'empilement de l'export par couches reste verte. Enregistré comme <b>modèle</b>, ce verso garde ses réglages mais <b>pas ses fichiers</b> : ils restent dans ce jeu.", "en": " <b>{n} / {max}</b> layer: the list order IS the paint order, and “Multiply” is <b>baked into the layer's pixels</b> — the layered-export stacking proof stays green. Saved as a <b>template</b>, this back keeps its settings but <b>not its files</b>: they stay in this deck."},
  "cartes.frame2.dos_catalogue": {"fr": "Dos du catalogue — <b>{nom}</b>. « Personnalisé » remplace le motif par une image importée, plus une pile de calques.", "en": "Catalogue back — <b>{nom}</b>. “Custom” replaces the pattern with an imported image, plus a layer stack."},
  "cartes.frame2.dos_image": {"fr": "Image de fond <b>{nom}</b>, cadrée en COUVERTURE depuis le bord de <b>toile</b> — fond perdu compris, pour qu'un massicot décalé ne pose pas la matière de bande sur l'arête de la carte.", "en": "Background image <b>{nom}</b>, fitted to COVER from the <b>canvas</b> edge — bleed included, so an off-register trim doesn't put band material on the card's edge."},
  "cartes.frame2.dos_sans_image": {"fr": "<b>Aucune image de fond</b> — déposez-en une ici, collez-la (Ctrl+V) ou choisissez un fichier.", "en": "<b>No background image</b> — drop one here, paste it (Ctrl+V) or choose a file."},
