  "cartes.frame2.png_filtre": {"fr": "filtre PNG inconnu : {ft}", "en": "unknown PNG filter: {ft}"},
  "cartes.frame2.png_format": {"fr": "PNG {d} bits, type {t}, entrelacement {i} : ce décodeur lit 8 bits RGB/RGBA non entrelacé", "en": "PNG {d}-bit, type {t}, interlace {i}: this decoder reads non-interlaced 8-bit RGB/RGBA"},
  "cartes.frame2.png_sans_ihdr": {"fr": "PNG sans IHDR", "en": "PNG without IHDR"},
  "cartes.frame2.png_signature": {"fr": "ce ne sont pas des octets PNG (signature absente)", "en": "these are not PNG bytes (signature missing)"},
  "cartes.frame2.preuve_attente": {"fr": "Elle part <b>toute seule</b> à l'ouverture et repart à chaque fois que le fichier change — le fichier est rendu par le <b>vrai chemin d'export</b> (le même que le bouton de téléchargement), puis ses octets sont relus ici : chunks, <b>zlib décompressé</b> et lignes <b>défiltrées</b> à la main (les 5 filtres de la norme). Chaque ligne ci-dessous confronte un chiffre de cet écran à ce que les échantillons disent.", "en": "It starts <b>on its own</b> when opened and restarts whenever the file changes — the file is rendered by the <b>real export path</b> (the same as the download button), then its bytes are re-read here: chunks, <b>zlib decompressed</b> and rows <b>unfiltered</b> by hand (the standard's 5 filters). Each row below checks a number on this screen against what the samples say."},
  "cartes.frame2.prof_courant": {"fr": "réglages courants", "en": "current settings"},
  "cartes.frame2.prof_max": {"fr": "curseurs au maximum", "en": "sliders at maximum"},
  "cartes.frame2.recto": {"fr": "recto", "en": "front"},
  "cartes.frame2.relecture": {"fr": "relecture des octets…", "en": "re-reading bytes…"},
  "cartes.frame2.relecture_recto": {"fr": "rendu puis relecture des octets du recto…", "en": "rendering then re-reading the front's bytes…"},
  "cartes.frame2.relecture_verso": {"fr": "rendu puis relecture des octets du verso…", "en": "rendering then re-reading the back's bytes…"},
  "cartes.frame2.rendu_recto": {"fr": "rendu du recto à l'échelle 1…", "en": "rendering the front at 1:1…"},
  "cartes.frame2.rendu_verso": {"fr": "rendu du verso à l'échelle 1…", "en": "rendering the back at 1:1…"},
  "cartes.frame2.retirer": {"fr": "retirer ce calque", "en": "remove this layer"},
