  "cartes.frame2.seule_depense": {"fr": " C'est la seule action de cet écran qui dépense.", "en": " This is the only action on this screen that spends money."},
  "cartes.frame2.sw_badge_cours": {"fr": "{g} géométries · rendus {k}/{n} couples…", "en": "{g} geometries · renders {k}/{n} pairs…"},
  "cartes.frame2.sw_badge_ok": {"fr": "{g} géométries + {r} rendus, 0 échec · {t}", "en": "{g} geometries + {r} renders, 0 failures · {t}"},
  "cartes.frame2.sw_coin_invisible": {"fr": "{ou} : ornement « {nom} » invisible", "en": "{ou}: ornament “{nom}” invisible"},
  "cartes.frame2.sw_coins_a": {"fr": "les {n} ornements changent le dessin sur les {k} couples (format, rayon, profil)", "en": "all {n} ornaments change the drawing on the {k} (format, radius, profile) pairs"},
  "cartes.frame2.sw_coins_note": {"fr": "rendu sans ornement puis avec, différence sur la luminance", "en": "rendered without the ornament then with it, difference on luminance"},
  "cartes.frame2.sw_coins_q": {"fr": "Ornements de coin", "en": "Corner ornaments"},
  "cartes.frame2.sw_echec": {"fr": "{ou} : {err}", "en": "{ou}: {err}"},
  "cartes.frame2.sw_geo_a": {"fr": "{n} géométries (x 2 profils de curseurs), aucune largeur ≤ 0", "en": "{n} geometries (x 2 slider profiles), no width ≤ 0"},
  "cartes.frame2.sw_geo_ko": {"fr": "{n} dégénérée(s) : {liste}", "en": "{n} degenerate: {liste}"},
  "cartes.frame2.sw_geo_note": {"fr": "toiles données par geomOf, passées au model() du painter — pas une réimplémentation", "en": "canvases from geomOf, fed to the painter's model() — not a reimplementation"},
  "cartes.frame2.sw_geo_ok": {"fr": "0 dégénérée · la plus serrée : {fmt} rayon {r} mm ({prof}), {mini} mm de largeur utile — bande {bw} x {bh} mm", "en": "0 degenerate · tightest: {fmt} radius {r} mm ({prof}), {mini} mm usable width — band {bw} x {bh} mm"},
  "cartes.frame2.sw_geo_q": {"fr": "Géométrie — 12 fmt x 2 rayons", "en": "Geometry — 12 formats x 2 radii"},
  "cartes.frame2.sw_ko_m": {"fr": "{n} : {liste}", "en": "{n}: {liste}"},
  "cartes.frame2.sw_ko_q": {"fr": "Échecs du balayage", "en": "Sweep failures"},
  "cartes.frame2.sw_lecture": {"fr": "Balayage à <b>{dpi} DPI</b> — c'est une vérification de <b>géométrie et de présence</b>, pas de netteté : la netteté se mesure sur le fichier livré, au-dessus. <b>{n} rendus</b> hors écran en {ms} ms, par les <b>painters du fichier</b> et sur des toiles rendues par <b>geomOf</b>. Rien n'est écrit dans le document : format, rayon, ornement et métal sont passés en surcharge locale, comme pour les vignettes. Formats les plus hostiles retenus pour le dessin : <b>{liste}</b> — le plus petit, le plus allongé, le plus grand.", "en": "Sweep at <b>{dpi} DPI</b> — this checks <b>geometry and presence</b>, not sharpness: sharpness is measured on the delivered file, above. <b>{n} renders</b> off-screen in {ms} ms, by the <b>file's painters</b> on canvases computed by <b>geomOf</b>. Nothing is written to the document: format, radius, ornament and metal are passed as local overrides, as for the thumbnails. Most hostile formats used for drawing: <b>{liste}</b> — the smallest, the most elongated, the largest."},
  "cartes.frame2.sw_max_a": {"fr": "bande > 0 mm sur les 12 formats, marge demandée à {mm} mm", "en": "band > 0 mm on all 12 formats, margin requested at {mm} mm"},
  "cartes.frame2.sw_max_m": {"fr": "la plus serrée : {fmt} rayon {r} mm → bande {bw} x {bh} mm, plaque {pw} x {ph} mm", "en": "tightest: {fmt} radius {r} mm → band {bw} x {bh} mm, plate {pw} x {ph} mm"},
