  "cartes.frame3.combinaisons": {"fr": "<b>{n}</b> combinaisons <i>(</i>{f} familles <i>x</i> {r} raretés<i>)</i>", "en": "<b>{n}</b> combinations <i>(</i>{f} families <i>x</i> {r} rarities<i>)</i>"},
  "cartes.frame3.confiance": {"fr": "confiance {n}", "en": "confidence {n}"},
