  "cartes.frame3.echec_retour": {"fr": " — <b>ÉCHEC du retour</b> : {err}", "en": " — <b>restore FAILED</b>: {err}"},
  "cartes.frame3.edge_attention": {"fr": " <b>Attention</b> : sur cette carte, une couche posée par-dessus le cadre (texte ou illustration) déborde du trait de coupe.", "en": " <b>Warning</b>: on this card, a layer placed over the frame (text or art) spills past the cut line."},
  "cartes.frame3.edge_axe": {"fr": " · axe à {mm} mm = {px} px de la coupe, soit {toile} px du bord de <b>toile</b>.", "en": " · axis at {mm} mm = {px} px from the cut, i.e. {toile} px from the <b>canvas</b> edge."},
  "cartes.frame3.edge_convention": {"fr": "Convention du <b>trait centré</b> : la valeur porte l'<b>axe</b>. Avec un filet de {line} mm, l'encre occupe de <b>{ext} mm</b> ({extpx} px) à <b>{int} mm</b> ({intpx} px) depuis le trait de coupe", "en": "<b>Centred stroke</b> convention: the value sets the <b>axis</b>. With a {line} mm rule, the ink spans <b>{ext} mm</b> ({extpx} px) to <b>{int} mm</b> ({intpx} px) from the cut line"},
  "cartes.frame3.edge_mord": {"fr": " — <b>le filet mord sur le fond perdu</b> : la coupe passe dedans.", "en": " — <b>the rule bites into the bleed</b>: the cut runs through it."},
  "cartes.frame3.edge_ton": {"fr": " Le fond de l'anneau garde le <b>même ton</b> de part et d'autre du trait de coupe : si la lame passe à ± {tol} mm, le bord de la carte a le même aspect et l'arête du filet reste la seule de la zone.", "en": " The ring background keeps the <b>same tone</b> on both sides of the cut line: if the blade lands ± {tol} mm off, the card edge looks the same and the rule's edge remains the only one in the area."},
  "cartes.frame3.egal_mm_dpi": {"fr": "{n} = {mm} mm à {dpi} DPI", "en": "{n} = {mm} mm at {dpi} DPI"},
  "cartes.frame3.empreinte_bougee": {"fr": " — l'empreinte a bougé pendant la mesure (une couche voisine suit la définition) ; les deux fichiers, eux, ont été rendus à la suite.", "en": " — the fingerprint moved during the measurement (a neighbouring layer follows the resolution); the two files themselves were rendered back to back."},
  "cartes.frame3.empreinte_maintenant": {"fr": " — l'empreinte vaut maintenant {sig}, la relecture repart.", "en": " — the fingerprint is now {sig}; re-reading again."},
  "cartes.frame3.empreinte_mesuree": {"fr": "Empreinte mesurée : {sig}", "en": "Measured fingerprint: {sig}"},
