  "cartes.frame3.pbadge_titre": {"fr": "Empreinte vérifiée : {sig} (géométrie + document + carte courante). Relecture {mode} à {at}", "en": "Verified fingerprint: {sig} (geometry + document + current card). Re-read ({mode}) at {at}"},
