  "cartes.gltf.atlas_importe": {"fr": "atlas importé : {nom} — {res}", "en": "atlas imported: {nom} — {res}"},
  "cartes.gltf.atlas_importe_note": {"fr": "Atlas importé : il part tel quel dans les maps et dans le GLB.", "en": "Imported atlas: it goes as-is into the maps and the GLB."},
  "cartes.gltf.aucun_atlas": {"fr": "Aucun atlas encore composé.", "en": "No atlas composed yet."},
