  "cartes.gltf.dossier_jeu_dir": {"fr": "dossier du jeu › <code>{dir}</code>", "en": "deck folder › <code>{dir}</code>"},
  "cartes.gltf.echelle_noeud": {"fr": "1 unité glTF = 1 mètre : le nœud porte l'échelle physique, sinon un viewer annoncerait une carte de {dim} m.", "en": "1 glTF unit = 1 meter: the node carries the physical scale, otherwise a viewer would report a {dim} m card."},
  "cartes.gltf.emi_cablee": {"fr": "la map émission part câblée (emissiveTexture + map_Ke)", "en": "the emission map ships wired (emissiveTexture + map_Ke)"},
  "cartes.gltf.emi_eteinte": {"fr": "réglage local <b>0</b> — émission éteinte, la map n'est pas écrite (même sur dorure ou holographique)", "en": "local setting <b>0</b> — emission off, the map is not written (even on foil or holographic)"},
  "cartes.gltf.emi_finition": {"fr": "celle de la finition : <b>{e}</b>", "en": "the finish's: <b>{e}</b>"},
  "cartes.gltf.emi_locale": {"fr": "réglage local <b>{ov}</b> — la map émission part câblée des deux côtés (emissiveTexture dans le GLB, map_Ke dans le MTL), le facteur du fichier vaudra [{ov}, {ov}, {ov}]", "en": "local setting <b>{ov}</b> — the emission map ships wired on both sides (emissiveTexture in the GLB, map_Ke in the MTL), the file factor will be [{ov}, {ov}, {ov}]"},
  "cartes.gltf.emi_zero": {"fr": "à 0, aucune map émission n'est écrite. Posez une valeur pour la câbler sans changer la matière (encre luminescente).", "en": "at 0, no emission map is written. Set a value to wire it without changing the material (glow ink)."},
  "cartes.gltf.emission_lbl": {"fr": "Émission", "en": "Emission"},
