  "cartes.gltf.export_garde": {"fr": "l'export garde les {cible} DPI posés dans la barre du document", "en": "the export keeps the {cible} DPI set in the document bar"},
  "cartes.gltf.export_sous": {"fr": "l'export descend sous les {cible} DPI posés dans la barre du document", "en": "the export falls below the {cible} DPI set in the document bar"},
  "cartes.gltf.face_atlas": {"fr": "Face dans l'atlas : <b>{px} px</b> — <b>{dx} x {dy} DPI</b> de texels", "en": "Face in the atlas: <b>{px} px</b> — <b>{dx} x {dy} DPI</b> of texels"},
  "cartes.gltf.face_texels": {"fr": "Face : <b>{px} px</b>, texels <b>{dx} x {dy} DPI</b> <i>(c'est cette densité qui partira dans le chunk pHYs de chaque PNG)</i>", "en": "Face: <b>{px} px</b>, texels <b>{dx} x {dy} DPI</b> <i>(this is the density written to the pHYs chunk of each PNG)</i>"},
  "cartes.gltf.faibles_plusieurs": {"fr": "{noms} varient trop peu pour se voir, sans être constantes", "en": "{noms} vary too little to show, without being constant"},
  "cartes.gltf.faibles_un": {"fr": "{noms} varie trop peu pour se voir, sans être constante", "en": "{noms} varies too little to show, without being constant"},
