  "cartes.gltf.gaspillage": {"fr": "<b>{pct} %</b> des texels de l'îlot recto portent de l'information : <b>{n}</b> texels n'en portent aucune.", "en": "<b>{pct}%</b> of the front island's texels carry detail: <b>{n}</b> texels carry none."},
  "cartes.gltf.geste": {"fr": "« Télécharger » en pose une copie dans le dossier de téléchargements du navigateur ; celui d'ici ne bouge pas.", "en": "“Download” puts a copy in the browser's downloads folder; the one here stays put."},
  "cartes.gltf.glb_ouvert": {"fr": "le .glb construit, ouvert ici", "en": "the built .glb, opened here"},
  "cartes.gltf.glisser_png": {"fr": "Glissez-déposez un PNG ici pour utiliser votre propre atlas.", "en": "Drag and drop a PNG here to use your own atlas."},
  "cartes.gltf.hors_reseau": {"fr": "<b>{pct} %</b> des échantillons <b>hors</b> du réseau k·257", "en": "<b>{pct}%</b> of samples <b>off</b> the k·257 lattice"},
  "cartes.gltf.ilot_recto": {"fr": "RECTO", "en": "FRONT"},
  "cartes.gltf.ilot_tranche": {"fr": "TRANCHE", "en": "EDGE"},
  "cartes.gltf.ilot_verso": {"fr": "VERSO", "en": "BACK"},
