  "cartes.gltf.verbe_reduit": {"fr": "<b class=\"cf-gltf-ko\">l'îlot la réduit</b> à", "en": "<b class=\"cf-gltf-ko\">the island shrinks it</b> to"},
  "cartes.gltf.vide_3mf": {"fr": "un <b>.3mf</b> — norme ouverte d'impression 3D, en millimètres, <b>avec la couleur</b>", "en": "a <b>.3mf</b> — open 3D printing standard, in millimeters, <b>with color</b>"},
  "cartes.gltf.vide_deck": {"fr": "plus un ZIP du <b>jeu entier</b> ({n} cartes)", "en": "plus a ZIP of the <b>whole deck</b> ({n} cards)"},
  "cartes.gltf.vide_glb": {"fr": "un <b>.glb</b> — géométrie, matériau, textures", "en": "a <b>.glb</b> — geometry, material, textures"},
  "cartes.gltf.vide_glb_emi": {"fr": "émission à zéro : aucune texture émissive, elle serait multipliée par zéro — voir le réglage Émission", "en": "emission at zero: no emissive texture, it would be multiplied by zero — see the Emission setting"},
  "cartes.gltf.vide_gltf": {"fr": "un <b>.gltf</b> autonome — buffer en data URI, aucun <i>.bin</i> à côté", "en": "a standalone <b>.gltf</b> — buffer as a data URI, no <i>.bin</i> alongside"},
  "cartes.gltf.vide_intro": {"fr": "Rien n'est encore construit. En <b>{res} px</b>, la construction produira :", "en": "Nothing built yet. At <b>{res} px</b>, the build will produce:"},
  "cartes.gltf.vide_obj": {"fr": "un <b>OBJ + MTL</b> en millimètres, avec ses maps", "en": "an <b>OBJ + MTL</b> in millimeters, with its maps"},
  "cartes.gltf.vide_stl": {"fr": "un <b>.stl</b> binaire en millimètres", "en": "a binary <b>.stl</b> in millimeters"},
  "cartes.gltf.vide_zip": {"fr": "un <b>.zip</b> — les maps PNG (une par canal dérivé, l'émission seulement si elle est non nulle — finition ou réglage), le manifeste, le maillage OBJ et son MTL", "en": "a <b>.zip</b> — the PNG maps (one per derived channel, emission only if non-zero — finish or setting), the manifest, the OBJ mesh and its MTL"},
  "cartes.gltf.visionneuse_absente": {"fr": "La visionneuse 3D (/assets/model-viewer.min.js) n'est pas chargée. Le fichier, lui, est construit et téléchargeable.", "en": "The 3D viewer (/assets/model-viewer.min.js) is not loaded. The file itself is built and downloadable."},
  "cartes.gltf.visionneuse_attente": {"fr": "La visionneuse ouvrira le <b>.glb</b> une fois construit et mesurera sa boîte englobante. Le nombre s'affichera ici, relu dans le fichier livré.", "en": "The viewer will open the <b>.glb</b> once built and measure its bounding box. The number will show here, read back from the delivered file."},
  "cartes.gltf.visionneuse_ko": {"fr": "la visionneuse n'a pas pu ouvrir le GLB", "en": "the viewer could not open the GLB"},
  "cartes.gltf.vue_atlas": {"fr": "ce qui part dans le fichier", "en": "what goes into the file"},
  "cartes.gltf.vue_canaux": {"fr": "les maps côte à côte — cochez « Planche de contrôle » et construisez", "en": "the maps side by side — tick “Proof sheet” and build"},
  "cartes.gltf.vue_ilots": {"fr": "les rectangles de l'atlas", "en": "the atlas rectangles"},
  "cartes.gltf.vue_uv": {"fr": "le fil de fer UV du maillage livré", "en": "UV wireframe of the delivered mesh"},
  "cartes.gltf.why_ao_non": {"fr": "à brancher à la main si votre moteur l'attend", "en": "wire it by hand if your engine expects it"},
  "cartes.gltf.why_ao_oui": {"fr": "l'ombre de contact est dans le fichier, pas à refaire à l'import", "en": "contact shadowing is in the file, nothing to redo on import"},
  "cartes.gltf.why_boite": {"fr": "relue dans les float32 de POSITION du chunk binaire, à l'échelle du nœud", "en": "read back from the POSITION float32 values of the binary chunk, at node scale"},
  "cartes.gltf.why_bornes": {"fr": "arrondies, le validateur glTF de référence refuse le fichier (ACCESSOR_MIN_MISMATCH)", "en": "if rounded, the reference glTF validator rejects the file (ACCESSOR_MIN_MISMATCH)"},
  "cartes.gltf.why_clamp": {"fr": "sur un atlas c'est le seul réglage sûr : en REPEAT, le filtrage du bord droit va chercher l'autre face", "en": "on an atlas this is the only safe setting: with REPEAT, filtering at the right edge samples the other face"},
  "cartes.gltf.why_double_face": {"fr": "surface ouverte : la double face évite les trous noirs", "en": "open surface: double-sided avoids black holes"},
  "cartes.gltf.why_emet": {"fr": "cette finition émet : la texture d'émission part avec le fichier", "en": "this finish emits: the emission texture ships with the file"},
  "cartes.gltf.why_emet_pas": {"fr": "cette finition n'émet pas — aucune texture d'émission n'est embarquée, elle serait multipliée par zéro", "en": "this finish does not emit — no emission texture is embedded, it would be multiplied by zero"},
  "cartes.gltf.why_extensions": {"fr": "un moteur qui ne les connaît pas rend la carte sans elles, jamais en erreur : c'est la règle des extensions glTF", "en": "an engine that doesn't know them renders the card without them, never with an error: that is the glTF extension rule"},
  "cartes.gltf.why_ferme": {"fr": "aucun trou : le maillage se remplit", "en": "no holes: the mesh can be filled"},
  "cartes.gltf.why_materiaux": {"fr": "un seul matériau pour toute la carte : un seul appel de rendu", "en": "a single material for the whole card: a single draw call"},
  "cartes.gltf.why_metal": {"fr": "laissez-le tel quel : la métallicité est déjà cuite dans la map, la remultiplier la compterait deux fois", "en": "leave it as is: metalness is already baked into the map, multiplying again would count it twice"},
  "cartes.gltf.why_ouvert": {"fr": "un maillage ouvert ne se remplit pas", "en": "an open mesh cannot be filled"},
  "cartes.gltf.why_repeat": {"fr": "sur un atlas, le filtrage du bord droit ira chercher l'autre face de la carte", "en": "on an atlas, filtering at the right edge will sample the other face of the card"},
  "cartes.gltf.why_rough": {"fr": "même chose pour la rugosité", "en": "same for roughness"},
  "cartes.gltf.why_sans_tangent": {"fr": "sans TANGENT, chaque moteur recalcule les siennes et la normale peut rendre différemment d'un moteur à l'autre", "en": "without TANGENT, each engine recomputes its own and the normal map may render differently from one engine to another"},
  "cartes.gltf.why_simple_face": {"fr": "un solide fermé se rend en simple face : la face arrière n'est jamais vue, la dessiner double le coût", "en": "a closed solid renders single-sided: the back face is never seen, drawing it doubles the cost"},
  "cartes.gltf.why_tangent": {"fr": "TANGENT est écrit : votre moteur n'a pas à recalculer les tangentes, la normale rendra pareil partout", "en": "TANGENT is written: your engine does not have to recompute tangents, the normal map renders the same everywhere"},
  "cartes.gltf.zip_des_maps": {"fr": "ZIP des maps", "en": "Maps ZIP"},
  "cartes.gltf.zip_obj_une": {"fr": "Ces deux cases ne produisent qu'<b>une</b> archive : le <b>ZIP des maps</b> embarque déjà l'OBJ, le MTL et les mêmes PNG, l'archive OBJ n'en serait qu'une seconde copie. Elle n'est pas écrite.", "en": "These two boxes produce only <b>one</b> archive: the <b>Maps ZIP</b> already carries the OBJ, the MTL and the same PNGs, so the OBJ archive would just be a second copy. It is not written."},
