  "cartes.type2.verso": {"fr": "Verso", "en": "Back"},
  "cartes.type2.verso_min": {"fr": "verso", "en": "back"},
  "cartes.type2.verso_seul": {"fr": "verso seul", "en": "back only"},
  "cartes.type3.ad_encre": {"fr": "<b>{bloc}</b> : l'encre passe à {mm} mm du bord du cadre de composition — sous la marge optique de {opt} mm que ce panneau déclare. Les repères de coupe d'une rotative dérivent d'autant.", "en": "<b>{bloc}</b>: the ink comes within {mm} mm of the text frame edge — below the {opt} mm optical margin this panel declares. A rotary press's cut marks drift by that much."},
  "cartes.type3.ad_halo": {"fr": "<b>{bloc}</b> : le halo de l'ombre portée passe à {mm} mm du bord du cadre de composition — sous la marge optique de {opt} mm que ce panneau déclare (le corps des glyphes, lui, est à {corps} mm). Les repères de coupe d'une rotative dérivent d'autant.", "en": "<b>{bloc}</b>: the drop-shadow halo comes within {mm} mm of the text frame edge — below the {opt} mm optical margin this panel declares (the glyph bodies themselves are at {corps} mm). A rotary press's cut marks drift by that much."},
  "cartes.type3.ad_lowc": {"fr": "<b>{bloc}</b> : contraste mesuré {r}:1 contre le fond réellement derrière (médiane {med}:1), sous le seuil WCAG AA de {seuil}:1 à {pt} pt{calc}. Un contour, une ombre ou une plaque de fond règlent le cas.", "en": "<b>{bloc}</b>: measured contrast {r}:1 against the background actually behind it (median {med}:1), below the WCAG AA threshold of {seuil}:1 at {pt} pt{calc}. An outline, a shadow or a background plate fixes it."},
  "cartes.type3.ad_masque": {"fr": "<b>{bloc}</b> : {px} px d'encre sur {total} sont recouverts — {pc} % des glyphes ne sont pas dans le fichier livré.", "en": "<b>{bloc}</b>: {px} of {total} px of ink are covered — {pc} % of the glyphs are not in the delivered file."},
  "cartes.type3.ad_par": {"fr": "Recouvert par : {qui}.", "en": "Covered by: {qui}."},
  "cartes.type3.ad_par_aucun": {"fr": "Aucun recouvreur nommé parmi les couches : re-peindre et re-jouer la preuve.", "en": "No covering layer identified: repaint and rerun the proof."},
  "cartes.type3.ad_pipette": {"fr": "C'est le chiffre que rendra une pipette WCAG posée sur le fichier, et il ne dépend que de deux couleurs : assombrir le fond sous l'encre — ou lui poser une plaque — le remonte. Épaissir le contour, non : le contour n'agit que sur le relais.", "en": "That is the figure a WCAG eyedropper will give on the file, and it depends on only two colors: darkening the background under the ink — or giving it a plate — raises it. Thickening the outline does not: the outline only affects the relay."},
  "cartes.type3.ad_pixels": {"fr": ", relevé au pixel {a} pour l'encre et {b} pour le fond", "en": ", sampled at pixel {a} for the ink and {b} for the background"},
  "cartes.type3.ad_relais": {"fr": "<b>{bloc}</b> : lisible grâce à son contour ({r}:1 par le relais), mais l'encre seule contre le fond ne fait que {d}:1", "en": "<b>{bloc}</b>: legible thanks to its outline ({r}:1 via the relay), but the ink alone against the background only reaches {d}:1"},
  "cartes.type3.ad_seuil": {"fr": ", sous le seuil AA de {seuil}:1 à {pt} pt.", "en": ", below the AA threshold of {seuil}:1 at {pt} pt."},
  "cartes.type3.ad_vide": {"fr": "<b>{bloc}</b> : slot configuré, aucun glyphe posé. La zone reste vide dans le fichier livré.", "en": "<b>{bloc}</b>: slot configured, no glyph set. The area stays empty in the delivered file."},
  "cartes.type3.api_derive": {"fr": " · le cadre de composition lui-même varie de {mm} mm entre les définitions du format ({dpis} DPI, soit {px} px de {dpi} DPI) : c'est la tolérance de ce relevé", "en": " · the text frame itself varies by {mm} mm across the format's resolutions ({dpis} DPI, i.e. {px} px at {dpi} DPI): that is this check's tolerance"},
  "cartes.type3.api_hors": {"fr": "{n} bloc(s) entament la marge du format", "en": "{n} block(s) cut into the format margin"},
  "cartes.type3.api_indispo": {"fr": "second comptage indisponible", "en": "second count unavailable"},
  "cartes.type3.api_ok": {"fr": "aucun bloc à reprendre", "en": "no block to rework"},
  "cartes.type3.api_recompte": {"fr": "recompté hors de l'écran : ", "en": "recounted off-screen: "},
  "cartes.type3.api_signe": {"fr": ", {n} avec un signe hors police", "en": ", {n} with an out-of-font character"},
  "cartes.type3.api_sous": {"fr": ", {n} sous le corps réglé", "en": ", {n} below the configured size"},
  "cartes.type3.appliquer": {"fr": "Appliquer", "en": "Apply"},
  "cartes.type3.audit_cours": {"fr": "contrôle photométrique en cours sur le composite…", "en": "photometric check running on the composite…"},
  "cartes.type3.audit_err": {"fr": "contrôle impossible : {err}", "en": "check failed: {err}"},
  "cartes.type3.audit_go": {"fr": "Contrôler maintenant", "en": "Check now"},
  "cartes.type3.audit_off": {"fr": "contrôle photométrique désactivé — les compteurs ci-dessus ne parlent que de géométrie.", "en": "photometric check off — the counters above only cover geometry."},
  "cartes.type3.canaux": {"fr": "{n} canal", "en": "{n} channel(s)"},
  "cartes.type3.cible_centre": {"fr": "centre de carte", "en": "card center"},
  "cartes.type3.cible_fenetre": {"fr": "fenêtre d’illustration", "en": "art window"},
