  "coque.accueil.bienvenue": {"fr": "Bienvenue", "en": "Welcome"},
  "coque.accueil.bienvenue_texte": {"fr": "Deepotus transforme une simple image (ou une actu, ou une phrase) en vidéo 9:16 finie et l'envoie sur chaque canal où vit le banc. Il nous faut juste quelques identifiants et un pseudo.", "en": "Deepotus turns a single image (or a news item, or a sentence) into a finished 9:16 video and ships it to every channel where the shoal lives. We just need a few credentials and a handle."},
  "coque.accueil.bienvenue_titre": {"fr": "Vous allez piloter un studio.", "en": "You are about to pilot a studio."},
  "coque.accueil.canal_instagram": {"fr": "Nécessite un compte Business relié à une Page Facebook.", "en": "Requires Business account on a Facebook Page."},
  "coque.accueil.canal_telegram": {"fr": "Jeton du bot + ID du chat du canal via @BotFather.", "en": "Bot token + channel chat ID via @BotFather."},
  "coque.accueil.canal_tiktok": {"fr": "Direct Post ; sans audit, les envois sont privés (SELF_ONLY).", "en": "Direct Post; without an audit, uploads are private (SELF_ONLY)."},
  "coque.accueil.canal_x": {"fr": "Publie fils et réponses via l'API v2.", "en": "Posts threads and replies via API v2."},
  "coque.accueil.canal_youtube": {"fr": "Envoie les Shorts sur votre chaîne via OAuth.", "en": "OAuth uploads Shorts to your channel."},
  "coque.accueil.canaux_attente": {"fr": "Canaux en attente", "en": "Channels pending"},
  "coque.accueil.canaux_connectes": {"fr": "Canaux connectés", "en": "Channels connected"},
  "coque.accueil.canaux_texte": {"fr": "Le Planificateur envoie les rendus finis vers tout ce qui est connecté ici. Connectez-les depuis Réglages → Comptes connectés ; les badges ci-dessous montrent ce qui est actif.", "en": "The Scheduler ships finished renders to whatever is connected here. Connect any from Settings → Connected accounts; the badges below reflect what is live."},
  "coque.accueil.canaux_titre": {"fr": "Connectez vos canaux.", "en": "Connect your channels."},
  "coque.accueil.carte_autopost": {"fr": "Publication auto", "en": "Auto-post"},
  "coque.accueil.carte_planificateur": {"fr": "Programmer les posts jour par jour.", "en": "Queue posts per day."},
  "coque.accueil.carte_studio": {"fr": "Composer des graphes.", "en": "Compose graphs."},
