  "etabli.et1_imp.slicer_titre": {"fr": "Prendre le preset sélectionné dans OrcaSlicer (lu, jamais modifié)", "en": "Use the preset selected in OrcaSlicer (read, never modified)"},
  "etabli.et1_imp.titre": {"fr": "Imprimante", "en": "Printer"},
  "etabli.et1_imprimer.aucun_modele": {"fr": "aucun modèle chargé", "en": "no model loaded"},
  "etabli.et1_imprimer.en_attente": {"fr": "{n} modification(s) en attente — écris-les d'abord : l'impression lit le fichier", "en": "{n} pending change(s) — write them first: printing reads the file"},
  "etabli.et1_imprimer.ensuite": {"fr": " — « Ouvrir dans le slicer » ensuite", "en": " — then “Open in the slicer”"},
  "etabli.et1_imprimer.exportee": {"fr": "version {v} exportée pour l'impression : {n} triangles, STL + 3MF dans {d}", "en": "version {v} exported for printing: {n} triangles, STL + 3MF in {d}"},
  "etabli.et1_imprimer.refusee": {"fr": "impression refusée : {m}", "en": "print refused: {m}"},
  "etabli.et1_imprimer.taille_cible": {"fr": "pose une taille cible (rail de droite) — un fichier 3D ne porte aucun millimètre", "en": "set a target size (right rail) — a 3D file carries no millimeters"},
  "etabli.et1_imprimer.version_d_abord": {"fr": "écris d'abord une version : une tâche Meshy s'imprime une fois adoptée par l'Établi", "en": "write a version first: a Meshy task can be printed once the Workbench has adopted it"},
  "etabli.et1_lex.assise_texte": {"fr": "La face qui touche le plateau. Large et plate, l'impression tient ; étroite, elle se décolle.", "en": "The face that touches the bed. Wide and flat, the print holds; narrow, it comes loose."},
  "etabli.et1_lex.assise_titre": {"fr": "Assise", "en": "Base (bed contact)"},
  "etabli.et1_lex.brim_texte": {"fr": "Collerette d'une couche autour de la pièce, contre le décollement des coins.", "en": "A one-layer collar around the part, to keep its corners from lifting."},
  "etabli.et1_lex.brim_titre": {"fr": "Brim", "en": "Brim"},
  "etabli.et1_lex.couche_texte": {"fr": "Tranche horizontale. 0,2 mm est le compromis courant ; 0,12 mm pour du détail.", "en": "A horizontal slice. 0.2 mm is the usual compromise; 0.12 mm for detail."},
  "etabli.et1_lex.couche_titre": {"fr": "Couche", "en": "Layer", "contexte": true},
  "etabli.et1_lex.couture_texte": {"fr": "Ligne verticale laissée par le début et la fin de chaque tour de paroi. Le slicer la place ou la disperse.", "en": "The vertical line left where each wall loop starts and ends. The slicer places it or scatters it."},
  "etabli.et1_lex.couture_titre": {"fr": "Couture", "en": "Seam"},
  "etabli.et1_lex.creusage_texte": {"fr": "Remplacer l'intérieur plein par une coque. Surtout utile en résine ; 2 mm pour commencer.", "en": "Replacing the solid inside with a shell. Mostly useful in resin; 2 mm to start."},
  "etabli.et1_lex.creusage_titre": {"fr": "Creusage", "en": "Hollowing"},
  "etabli.et1_lex.decimation_texte": {"fr": "Réduire le nombre de triangles. 500 000 ne s'impriment pas mieux que 100 000, mais ralentissent tout.", "en": "Reducing the triangle count. 500,000 print no better than 100,000, but slow everything down."},
  "etabli.et1_lex.decimation_titre": {"fr": "Décimation", "en": "Decimation"},
  "etabli.et1_lex.drainage_texte": {"fr": "Le trou qui laisse sortir la résine (et l'air) d'une pièce creusée. Fiche → « Percer (drainage) », puis un clic sur la face.", "en": "The hole letting resin (and air) out of a hollowed part. Report → “Drill (drain hole)”, then a click on the face."},
  "etabli.et1_lex.drainage_titre": {"fr": "Drainage", "en": "Drain hole"},
  "etabli.et1_lex.etancheite_texte": {"fr": "Surface fermée, sans trou ni bord libre. C'est le « fermé » de la barre du bas.", "en": "A closed surface, with no hole or free edge. It is the “closed” of the bottom bar."},
  "etabli.et1_lex.etancheite_titre": {"fr": "Étanchéité", "en": "Watertightness"},
  "etabli.et1_lex.jupe_texte": {"fr": "Contour tracé à côté de la pièce pour amorcer le flux avant de commencer.", "en": "An outline drawn next to the part, to prime the flow before starting."},
  "etabli.et1_lex.jupe_titre": {"fr": "Jupe (skirt)", "en": "Skirt"},
  "etabli.et1_lex.manifold_texte": {"fr": "Chaque arête appartient à exactement deux faces. Un maillage peut être fermé ET non-manifold.", "en": "Every edge belongs to exactly two faces. A mesh can be closed AND non-manifold."},
  "etabli.et1_lex.manifold_titre": {"fr": "Manifold", "en": "Manifold"},
  "etabli.et1_lex.perimetre_texte": {"fr": "Nombre de tours de paroi. Deux à 0,45 mm font 0,9 mm : le minimum à viser en modélisant.", "en": "The number of wall loops. Two at 0.45 mm make 0.9 mm: the minimum to aim for when modeling."},
  "etabli.et1_lex.perimetre_titre": {"fr": "Périmètre", "en": "Perimeter (wall)", "contexte": true},
  "etabli.et1_lex.pont_texte": {"fr": "Couche imprimée au-dessus du vide entre deux appuis. Quelques centimètres, avec un bon refroidissement.", "en": "A layer printed over empty space, between two supports. A few centimeters, with good cooling."},
  "etabli.et1_lex.pont_titre": {"fr": "Pont", "en": "Bridging"},
  "etabli.et1_lex.raft_texte": {"fr": "Radeau imprimé sous toute la pièce. Plus sûr qu'un brim, plus coûteux, face rugueuse.", "en": "A platform printed under the whole part. Safer than a brim, costlier, rough face."},
  "etabli.et1_lex.raft_titre": {"fr": "Raft", "en": "Raft"},
  "etabli.et1_lex.remplissage_texte": {"fr": "Motif de l'intérieur. 15 % suffisent le plus souvent ; le gyroïde résiste à peu près autant dans tous les sens.", "en": "The pattern inside. 15 % is usually enough; gyroid is about equally strong in every direction."},
  "etabli.et1_lex.remplissage_titre": {"fr": "Remplissage", "en": "Infill", "contexte": true},
  "etabli.et1_lex.retraction_texte": {"fr": "Le filament est tiré en arrière pendant les déplacements, contre les fils.", "en": "Filament pulled back during travel moves, to avoid strings."},
  "etabli.et1_lex.retraction_titre": {"fr": "Rétraction", "en": "Retraction"},
  "etabli.et1_lex.support_texte": {"fr": "Structure jetable qui soutient les surplombs. Le slicer la génère ; l'Établi aide à en avoir moins besoin.", "en": "A disposable structure holding overhangs up. The slicer generates it; the Workbench helps you need less of it."},
  "etabli.et1_lex.support_titre": {"fr": "Support", "en": "Support"},
  "etabli.et1_lex.surplomb_texte": {"fr": "Une paroi trop penchée pour tenir sur la couche d'en dessous. Sous 45 à 60° depuis l'horizontale, il faut un support.", "en": "A wall leaning too far to rest on the layer below. Under 45 to 60° from horizontal, it needs a support."},
  "etabli.et1_lex.surplomb_titre": {"fr": "Surplomb", "en": "Overhang"},
  "etabli.et1_lex.warping_texte": {"fr": "Coins qui se soulèvent en refroidissant. Plateau propre, brim, enceinte fermée.", "en": "Corners lifting as they cool. Clean bed, brim, closed enclosure."},
  "etabli.et1_lex.warping_titre": {"fr": "Warping", "en": "Warping"},
