  "etabli.et1_orient.choix": {"fr": "pose {k} — appui {appui} · surplomb {surplomb} · hauteur {h} {u}", "en": "pose {k} — contact {appui} · overhang {surplomb} · height {h} {u}"},
  "etabli.et1_orient.pose": {"fr": "posé sur la pose {k} (version {v}) — appui {appui}, surplomb {surplomb}", "en": "placed in pose {k} (version {v}) — contact {appui}, overhang {surplomb}"},
