  "etabli.et1_outils.arranger": {"fr": "Ranger sur le plateau", "en": "Arrange on the bed"},
  "etabli.et1_outils.arranger_titre": {"fr": "Sur la plaque, sous une taille cible : range les pièces sur le plateau de l'imprimante active — rotation à plat, espacement, plusieurs plateaux au besoin (vue seulement, enregistrée comme la plaque)", "en": "On the plate, with a target size: arranges the parts on the active printer's bed — flat rotation, spacing, several beds if needed (view only, saved like the plate)"},
  "etabli.et1_outils.assise": {"fr": "Poser sur une face", "en": "Place on a face"},
  "etabli.et1_outils.assise_arme": {"fr": "Poser sur une face : cliquez une face (Échap annule)", "en": "Place on a face: click a face (Esc cancels)"},
  "etabli.et1_outils.assise_arme_titre": {"fr": "Cliquez la face du maillage qui doit toucher le sol — Échap pour renoncer", "en": "Click the mesh face that should touch the ground — Esc to give up"},
  "etabli.et1_outils.assise_titre": {"fr": "Touche F — la face cliquée devient l'assise : le modèle tourne pour qu'elle regarde le bas et se pose au contact (mis en attente, puis écrit par « écrire la version »)", "en": "F key — the clicked face becomes the base: the model rotates so that it faces down and rests in contact (queued, then written by “write the version”)"},
  "etabli.et1_outils.couteau": {"fr": "Couteau", "en": "Knife"},
  "etabli.et1_outils.couteau_arme_titre": {"fr": "Retirer le plan de coupe sans rien couper (Échap)", "en": "Remove the cutting plane without cutting anything (Esc)"},
  "etabli.et1_outils.couteau_ranger": {"fr": "Ranger le couteau", "en": "Put the knife away"},
  "etabli.et1_outils.couteau_titre": {"fr": "Touche C — un plan de coupe sur les pièces RETENUES dans Parties : déplacez-le, tournez-le, puis « Couper » écrit une version où chaque pièce devient deux pièces refermées", "en": "C key — a cutting plane on the parts SELECTED in Parts: move it, rotate it, then “Cut” writes a version where each part becomes two closed parts"},
  "etabli.et1_outils.mesurer": {"fr": "Mesurer", "en": "Measure"},
  "etabli.et1_outils.mesurer_arme": {"fr": "Mesurer : deux clics (Échap)", "en": "Measure: two clicks (Esc)"},
  "etabli.et1_outils.mesurer_titre": {"fr": "Deux clics sur le modèle : distance, composantes x/y/z et angle des deux faces", "en": "Two clicks on the model: distance, x/y/z components and the angle between the two faces"},
  "etabli.et1_outils.orienter": {"fr": "Orienter", "en": "Orient"},
  "etabli.et1_outils.orienter_titre": {"fr": "Propose trois poses classées (appui, surplomb, hauteur) dans l'onglet Fiche — rien n'est écrit tant que tu n'en choisis pas une, et c'est l'assise qui l'applique", "en": "Suggests three ranked poses (contact, overhang, height) in the Report tab — nothing is written until you choose one, and the base tool applies it"},
  "etabli.et1_outils.plan_deplacer": {"fr": "déplacer le plan", "en": "move the plane"},
  "etabli.et1_outils.plan_tourner": {"fr": "tourner le plan", "en": "rotate the plane"},
  "etabli.et1_outils.surplombs": {"fr": "Surplombs", "en": "Overhangs"},
  "etabli.et1_outils.surplombs_titre": {"fr": "Peint en orange les faces sous {seuil}° depuis l'horizontale (dans l'axe du plateau sur la plaque) — là où le slicer devra poser un support. Un regard : rien n'est écrit", "en": "Paints in orange the faces below {seuil}° from horizontal (along the bed axis on the plate) — where the slicer will need a support. Just a look: nothing is written"},
  "etabli.et1_outils.tranches": {"fr": "Tranches", "en": "Slices"},
  "etabli.et1_outils.tranches_titre": {"fr": "Aperçu de tranchage INDICATIF : {n} sections du modèle assemblé, tracées en bleu — pas de G-code, pas de support ; le slicer tranche pour de vrai", "en": "INDICATIVE slice preview: {n} sections of the assembled model, drawn in blue — no G-code, no support; the slicer does the real slicing"},
  "etabli.et1_piece.aucune_courante": {"fr": "aucune pièce courante — cliquez une pièce sur la plaque avant de la tourner", "en": "no current part — click a part on the plate before rotating it"},
  "etabli.et1_piece.coin": {"fr": "coin", "en": "corner", "contexte": true},
