  "matiere.mf1_plat.eteinte": {"fr": "éteinte", "en": "off"},
  "matiere.mf1_plat.mate_partout": {"fr": "mate partout", "en": "matte throughout"},
  "matiere.mf1_plat.metal_plein": {"fr": "métal plein", "en": "solid metal"},
  "matiere.mf1_plat.miroir_partout": {"fr": "miroir partout", "en": "mirror throughout"},
  "matiere.mf1_plat.plane": {"fr": "plane", "en": "flat"},
