  "matiere.mf1_plat.unie": {"fr": "unie", "en": "solid"},
  "matiere.mf1_plat.uniforme": {"fr": "uniforme", "en": "uniform"},
  "matiere.mf1_raccord.ancien": {"fr": " (Ancien score de bord avant la passe : {b} ; l'après vaut 0.00 par construction, il ne mesure rien.)", "en": " (Old edge score before the pass: {b}; the after value is 0.00 by construction, it measures nothing.)"},
  "matiere.mf1_raccord.avant": {"fr": "avant", "en": "before"},
  "matiere.mf1_raccord.bord_seul": {"fr": "Score de bord avant la passe : {b}. Rapport de jonction pas encore calculé pour cette matière.", "en": "Edge score before the pass: {b}. Junction ratio not computed yet for this material."},
  "matiere.mf1_raccord.mot": {"fr": "raccord", "en": "seam", "contexte": true},
  "matiere.mf1_raccord.note_def": {"fr": "1.00 = la jonction ne dépasse pas la variation interne du motif.", "en": "1.00 = the junction stays within the pattern’s own variation."},
  "matiere.mf1_raccord.titre": {"fr": "Raccord : {r} — {note} Paliers : ≤ {t1} invisible, ≤ {t2} discret, ≤ {top} visible, au-delà cassé — la jauge situe ce rapport sur cette échelle, les deux traits sont les seuils.", "en": "Seam: {r} — {note} Tiers: ≤ {t1} invisible, ≤ {t2} subtle, ≤ {top} visible, broken beyond that — the gauge places this ratio on that scale; the two marks are the thresholds."},
