  "montage.automation.aplatie": {"fr": "Automation aplatie — le clip revient au gain seul, payload d'avant.", "en": "Automation flattened — the clip goes back to plain gain, previous payload."},
  "montage.automation.plafond": {"fr": "Automation : {n} points maximum par clip (contrat du rendu).", "en": "Automation: {n} points maximum per clip (render contract)."},
